#!/bin/sh
# GENERATED by bake.py from /etc/event.d/ce-register-video-handler -- do not edit.
# Lives outside the job because upstart segfaults spawning a job
# with a large inline script (see externalise_job_scripts).
# Run by that job as `sh -e`: a lone failing command aborts it.
    FLAG=/var/luna/preferences/ce-video-handler-registered
    LOG=/var/log/ce-register-video-handler.log
    [ -f $FLAG ] && exit 0
    AM=palm://com.palm.applicationManager
    APP=com.palm.app.videos
    n=0
    while [ $n -lt 60 ]; do
        pidof LunaSysMgr >/dev/null 2>&1 && break
        sleep 2; n=$((n+1))
    done
    sleep 12
    mime_for_ext() {
        luna-send -n 1 $AM/mimeTypeForExtension "{\"extension\":\"$1\"}" </dev/null 2>/dev/null \
            | sed -n 's/.*"mimeType": *"\([^"]*\)".*/\1/p' | sed 's#\\/#/#g'
    }
    register() {
        [ -n "$2" ] || return 0
        luna-send -n 1 $AM/addResourceHandler \
            "{\"extension\":\"$1\",\"mimeType\":\"$2\",\"appId\":\"$APP\"}" \
            </dev/null >/dev/null 2>&1
        R=$(luna-send -n 1 $AM/listAllHandlersForMime "{\"mime\":\"$2\"}" </dev/null 2>&1)
        # only the activeHandler block counts -- the alternates follow it
        A=$(echo "$R" | sed -n 's/.*"activeHandler": *{\([^}]*\)}.*/\1/p')
        case "$A" in *$APP*) return 0 ;; esac
        IDX=$(echo "$R" | tr '}' '\n' | grep "$APP" | grep -o '"index": *[0-9]*' | grep -o '[0-9]*' | head -1)
        [ -n "$IDX" ] && luna-send -n 1 $AM/swapResourceHandler \
            "{\"mimeType\":\"$2\",\"index\":$IDX}" </dev/null >/dev/null 2>&1
    }
    register mp4 video/mp4
    register mp4 "$(mime_for_ext mp4)"
    register m4v video/x-m4v
    register m4v "$(mime_for_ext m4v)"
    register 3gp video/3gpp
    register 3gp "$(mime_for_ext 3gp)"
    register 3g2 video/3gpp2
    register 3g2 "$(mime_for_ext 3g2)"
    register mov video/quicktime
    register mov "$(mime_for_ext mov)"
    register webm video/webm
    register webm "$(mime_for_ext webm)"
    register mkv video/x-matroska
    register mkv "$(mime_for_ext mkv)"
    sleep 2
    mkdir -p /media/internal/downloads 2>/dev/null
    touch /media/internal/downloads/.ce-probe.mp4 2>/dev/null
    R=$(luna-send -n 1 $AM/getResourceInfo \
        '{"uri":"file:///media/internal/downloads/.ce-probe.mp4"}' </dev/null 2>&1)
    case "$R" in
        *$APP*canStream*true*|*canStream*true*$APP*)
            touch $FLAG
            echo "$(date 2>/dev/null) registered: $R" >> $LOG 2>/dev/null ;;
        *)
            echo "$(date 2>/dev/null) NOT registered, will retry next boot: $R" \
                 >> $LOG 2>/dev/null ;;
    esac
    rm -f /media/internal/downloads/.ce-probe.mp4 2>/dev/null
